('{\"en\":\"Dr. Jasmin Akter\",\"bn\":\"ডাঃ জেসমিন আক্তার\"}', 'dr-jasmin-akter', '{\"en\":\"Medical Officer\",\"bn\":\"মেডিকেল অফিসার\"}', '{\"en\":\"Obstetrics & Gynecology Specialist\",\"bn\":\"প্রসূতি ও মহিলা রোগ বিশেষজ্ঞ\"}', '{\"en\":\"MBBS (SOME), BCS (Health), CMU (Ultra)\",\"bn\":\"এমবিবিএস (এসওএমসি), বিসিএস (স্বাস্থ্য), সিএমইউ (আল্ট্রা)\"}', '{\"en\":\"Sitakunda Upazila Health Complex\",\"bn\":\"সীতাকুণ্ড উপজেলা স্বাস্থ্য কমপ্লেক্স\"}', '{\"en\":\"Dr. Jasmin Akter is an experienced Obstetrics & Gynecology specialist, Medical Officer at Sitakunda Upazila Health Complex. She sees patients at Medicare Lab every Saturday to Thursday, 2PM to 7PM.\",\"bn\":\"ডাঃ জেসমিন আক্তার একজন অভিজ্ঞ প্রসূতি ও মহিলা রোগ বিশেষজ্ঞ এবং সীতাকুণ্ড উপজেলা স্বাস্থ্য কমপ্লেক্সের মেডিকেল অফিসার। তিনি প্রতি শনিবার থেকে বৃহস্পতিবার দুপুর ২টা থেকে সন্ধ্যা ৭টা পর্যন্ত মেডিকেয়ার ল্যাবে রোগী দেখেন।\"}', NULL, '[{\"day\":{\"en\":\"Saturday to Thursday\",\"bn\":\"শনিবার – বৃহস্পতিবার\"},\"time\":{\"en\":\"2:00 PM – 7:00 PM\",\"bn\":\"দুপুর ২টা – সন্ধ্যা ৭টা\"}}]', '{\"en\":\"Medicare Lab (Faruk Medical Hall), Ali Market, Sitakunda Bazar, Chattogram\",\"bn\":\"মেডিকেয়ার ল্যাব (ফারুক মেডিকেল হল), আলী মার্কেট, সীতাকুণ্ড বাজার, চট্টগ্রাম\"}', '{\"en\":\"01711-307275, 01813-161010\",\"bn\":\"01711-307275, 01813-161010\"}', 1, 1, 0, NOW(), NOW()),
('{\"en\":\"Dr. Bilkis Akter\",\"bn\":\"ডাঃ বিলকিস আক্তার\"}', 'dr-bilkis-akter', '{\"en\":\"Consultant (Ortho-Surgery) Specialist\",\"bn\":\"কনসালটেন্ট (অর্থো-সার্জারি) বিশেষজ্ঞ\"}', '{\"en\":\"Orthopedics Specialist — Bone Fracture, Joint Pain & Spinal Disorders\",\"bn\":\"অর্থোপেডিক্স বিশেষজ্ঞ — হাড় ভাঙা জোড়া, বাত ব্যথা ও মেরুদণ্ড রোগ\"}', '{\"en\":\"MBBS, MS (Orthopedic Surgery)\",\"bn\":\"এমবিবিএস, এমএস (অর্থোপেডিক সার্জারি)\"}', '{\"en\":\"Chattogram Ma O Shishu Medical College & Hospital\",\"bn\":\"চট্টগ্রাম মা ও শিশু মেডিকেল কলেজ ও হাসপাতাল\"}', '{\"en\":\"Dr. Bilkis Akter is an experienced Orthopedics & Trauma Surgeon, Consultant at Chattogram Ma O Shishu Medical College Hospital. She sees patients at Medicare Lab every Saturday 3PM–7PM.\",\"bn\":\"ডাঃ বিলকিস আক্তার একজন অভিজ্ঞ অর্থোপেডিক ও ট্রমা সার্জন এবং চট্টগ্রাম মা ও শিশু মেডিকেল কলেজ হাসপাতালের কনসালটেন্ট। তিনি প্রতি শনিবার বিকাল ৩টা – ৭টা মেডিকেয়ার ল্যাবে রোগী দেখেন।\"}', '[{\"en\":\"Joint pain, bone fractures, reconnecting severed limbs\",\"bn\":\"বাত ব্যথা, হাড়ভাঙা, হাতের ও পায়ের কাটা অংশ জোড়া লাগানো\"},{\"en\":\"Numbness, tingling, weakness of hands & feet\",\"bn\":\"অসাড় হওয়া, ঝিমঝিম করা, দুর্বলতা\"},{\"en\":\"Treatment of any hand and foot problems\",\"bn\":\"হাতের ও পায়ের যে কোন ধরনের সমস্যার চিকিৎসা\"}]', '[{\"day\":{\"en\":\"Every Saturday\",\"bn\":\"প্রতি শনিবার\"},\"time\":{\"en\":\"3:00 PM – 7:00 PM\",\"bn\":\"বিকাল ৩টা – ৭টা\"}}]', '{\"en\":\"Medicare Lab (Faruk Medical Hall), Ali Market, Sitakunda Bazar, Chattogram\",\"bn\":\"মেডিকেয়ার ল্যাব (ফারুক মেডিকেল হল), আলী মার্কেট, সীতাকুণ্ড বাজার, চট্টগ্রাম\"}', '{\"en\":\"01711-307275, 01813-161010\",\"bn\":\"01711-307275, 01813-161010\"}', 2, 1, 0, NOW(), NOW()),
('{\"en\":\"Dr. Bibi Kulsum Sumi\",\"bn\":\"ডা. বিবি কুলসুম সুমি\"}', 'dr-bibi-kulsum-sumi', '{\"en\":\"Trained in Medical Ultrasonography\",\"bn\":\"টেইন্ড ইন মেডিকেল আন্ট্রাসনোগ্রাম\"}', '{\"en\":\"Obstetrics, Gynecology, Medicine & Infertility Specialist\",\"bn\":\"প্রসূতি, গাইনী, মেডিসিন ও বন্ধ্যাত্ব রোগের চিকিৎসক\"}', '{\"en\":\"MBBS, BCS (Health), PGT (Gynae & Obs), CMU, DMU\",\"bn\":\"এমবিবিএস, বিসিএস (স্বাস্থ্য), পিজিটি (গাইনী এন্ড অবস), সিএমইউ, ডিএমইউ\"}', '{\"en\":\"Sylhet Osmani Medical College Hospital\",\"bn\":\"সিলেট ওসমানী মেডিক্যাল কলেজ হাসপাতাল\"}', '{\"en\":\"Dr. Bibi Kulsum Sumi is an experienced specialist in Obstetrics, Gynecology, Medicine and Infertility, trained in medical ultrasonography. She sees patients at Medicare Lab every Thursday and Friday.\",\"bn\":\"ডা. বিবি কুলসুম সুমি প্রসূতি, গাইনী, মেডিসিন ও বন্ধ্যাত্ব রোগের একজন অভিজ্ঞ চিকিৎসক এবং মেডিকেল আল্ট্রাসনোগ্রামে প্রশিক্ষিত। তিনি প্রতি বৃহস্পতিবার ও শুক্রবার মেডিকেয়ার ল্যাবে রোগী দেখেন।\"}', NULL, '[{\"day\":{\"en\":\"Every Thursday\",\"bn\":\"প্রতি বৃহস্পতিবার\"},\"time\":{\"en\":\"From afternoon\",\"bn\":\"বিকাল থেকে\"}},{\"day\":{\"en\":\"Every Friday\",\"bn\":\"প্রতি শুক্রবার\"},\"time\":{\"en\":\"9AM–2PM \\/ 4PM–6PM\",\"bn\":\"সকাল ৯টা – দুপুর ২টা \\/ বিকাল ৪টা – সন্ধ্যা ৬টা\"}}]', '{\"en\":\"Medicare Lab (Faruk Medical Hall), Ali Market, Sitakunda Bazar, Chattogram\",\"bn\":\"মেডিকেয়ার ল্যাব (ফারুক মেডিকেল হল), আলী মার্কেট, সীতাকুণ্ড বাজার, চট্টগ্রাম\"}', '{\"en\":\"01711-307275, 01813-161010\",\"bn\":\"01711-307275, 01813-161010\"}', 3, 1, 0, NOW(), NOW()),
