('{\"en\":\"Dr. Md. Ashek Elahi\",\"bn\":\"ডাঃ মোঃ আশেক এলাহী\"}', 'dr-md-ashek-elahi', '{\"en\":\"Assistant Professor, Dermatology & Venereology\",\"bn\":\"সহযোগী অধ্যাপক, চর্ম ও যৌন রোগ বিভাগ\"}', '{\"en\":\"Dermatology & Venereology Specialist\",\"bn\":\"চর্ম ও যৌন রোগ বিশেষজ্ঞ\"}', '{\"en\":\"M.B.B.S, B.C.S (Health), MD Dermatology (CMEK)\",\"bn\":\"এম.বি.বি.এস, বি.সি.এস. (স্বাস্থ্য), এমডি-ডার্মাটোলজী (চমেক)\"}', '{\"en\":\"Assistant Professor\",\"bn\":\"সহযোগী অধ্যাপক\"}', '{\"en\":\"Dr. Md. Ashek Elahi is an Assistant Professor and specialist in Dermatology & Venereology. He sees patients at Medicare Lab every Saturday 4PM–7PM.\",\"bn\":\"ডাঃ মোঃ আশেক এলাহী সহযোগী অধ্যাপক এবং চর্ম ও যৌন রোগ বিশেষজ্ঞ। তিনি প্রতি শনিবার বিকাল ৪টা – সন্ধ্যা ৭টা মেডিকেয়ার ল্যাবে রোগী দেখেন।\"}', NULL, '[{\"day\":{\"en\":\"Every Saturday\",\"bn\":\"প্রতি শনিবার\"},\"time\":{\"en\":\"4:00 PM – 7:00 PM\",\"bn\":\"বিকাল ৪টা – সন্ধ্যা ৭টা\"}}]', '{\"en\":\"Medicare Lab (Faruk Medical Hall), Ali Market, Sitakunda Bazar, Chattogram\",\"bn\":\"মেডিকেয়ার ল্যাব (ফারুক মেডিকেল হল), আলী মার্কেট, সীতাকুণ্ড বাজার, চট্টগ্রাম\"}', '{\"en\":\"01711-307275, 01813-161010\",\"bn\":\"01711-307275, 01813-161010\"}', 5, 1, 0, NOW(), NOW()),
